package com.github.nyabanban.fuji.emulator.components.sdhost

import com.github.nyabanban.fuji.emulator.api.*
import org.junit.jupiter.api.Test
import java.nio.file.Path
import kotlin.test.*

class SdClockHostTest {
 private fun initial()=(0..1).associate{it.toString() to SdControlHost.fields.associateWith{0L}}
 private fun input(samples:List<Any?> = listOf(0,0,1)):Map<String,Any?> = mapOf("schema" to 1,"profile" to SdHostFactory.CLOCK_PROFILE,"initialRegisters" to initial(),"clocks" to (0..3).associate{SdClockHost.key(it) to mapOf("initialWord" to 0xa550L,"bit1Samples" to samples)})
 private class Context(var data:Map<String,Any?>):ComponentContext {
  var tick=1L;var reads=0;val entries=mutableMapOf<String,Any>();override val directory=Path.of("unused-sd-clock")
  override val clock=EmulationClock{tick}
  override val ports=object:Ports{override fun<T:Any>register(owner:String,name:String,type:Class<T>,port:T){check(entries.putIfAbsent(name,port)==null)};override fun<T:Any>find(name:String,type:Class<T>):T?=entries[name]?.let{type.cast(it)};override fun removeOwner(owner:String)=error("unexpected remove")}
  override val events=object:EventChannel{override fun publish(event:ComponentEvent)=error("no clock/card IRQ");override fun subscribe(listener:(ComponentEvent)->Unit):AutoCloseable=error("no subscriptions")}
  override fun dataPath(relative:String)=directory.resolve(relative)
  override fun readData(relative:String):Map<String,Any?>{reads++;return data}
 }
 private fun create(c:Context):HardwareComponent {val f=SdHostFactory();return f.create(c,f.descriptor.settings.associate{it.key to it.default}+mapOf("profile" to SdHostFactory.CLOCK_PROFILE,"inputFile" to "clock.yaml"))}
 private fun port(c:Context,index:Int)=c.ports.find(SdClockHost.port(index),MmioDevice::class.java)!!
 @Test fun explicitFourClocksAreIndependentAndBit1DoesNotOverwriteStoredWrites(){val c=Context(input());c.entries["cpu.execution-location"]=ExecutionLocationSource{ExecutionLocation(2,0x5aff8)};val h=create(c);h.start();assertEquals(1,c.reads);assertEquals(14,h.additionalMmioPorts().size);assertEquals((0..13).toSet(),c.entries.values.filterIsInstance<MmioDevice>().map{it.clockIndex}.toSet());for(i in 0..3){val p=port(c,i);assertEquals(0xa550L,p.read(0,2));p.write(0,2,0xa553);assertEquals(0xa551L,p.read(0,2));assertEquals(0xa553L,p.read(0,2))};val clocks=h.state()["clocks"]as Map<*,*>;assertTrue(clocks.values.all{val r=it as Map<*,*>;r["storedWord"]==0xa553L&&r["consumedSamples"]==3});assertTrue(h.interruptRoutes().isEmpty());assertEquals(false,h.state()["cardProtocolQualified"])}
 @Test fun missingNullExhaustedClockAndLocationFailuresNeverConsumeOrMutate(){for(samples in listOf(emptyList(),listOf(null))){val c=Context(input(samples));val h=create(c);val before=h.state();assertFails{port(c,0).read(0,2)};assertEquals(before,h.state())};val c=Context(input(listOf(0,1)));val h=create(c);val p=port(c,0);c.tick=-1;var before=h.state();assertFails{p.read(0,2)};assertFails{p.write(0,2,1)};assertEquals(before,h.state());c.tick=1;c.entries["cpu.execution-location"]=ExecutionLocationSource{error("location failure")};assertFails{p.read(0,2)};assertFails{p.write(0,2,1)};assertEquals(before,h.state());c.entries.remove("cpu.execution-location");assertEquals(0xa550L,p.read(0,2));assertEquals(0xa552L,p.read(0,2));before=h.state();assertFails{p.read(0,2)};assertEquals(before,h.state())}
 @Test fun malformedInputsAndAnyPortAliasRefuseBeforePublishing(){val base=input();val clocks=base["clocks"]as Map<*,*>;val row=clocks["0:0"]as Map<*,*>;val invalid=mutableListOf<Map<String,Any?>>();for(k in base.keys)invalid+=base-k;invalid+=base+mapOf("schema" to 1.0);invalid+=base+mapOf("extra" to 1);invalid+=base+mapOf("clocks" to(clocks-"1:1"));for(v in listOf(-1L,65536L,2L,1.0,true,"0"))invalid+=base+mapOf("clocks" to(clocks+mapOf("0:0" to(row+mapOf("initialWord" to v)))));for(v in listOf(listOf(-1),listOf(2),listOf(1.0),listOf(true),List(4097){0},"0"))invalid+=base+mapOf("clocks" to(clocks+mapOf("0:0" to(row+mapOf("bit1Samples" to v)))));invalid+=base+mapOf("initialRegisters" to mapOf("0" to emptyMap<String,Any>(),"1" to emptyMap<String,Any>()));for(data in invalid){val c=Context(data);assertFails{create(c)};assertTrue(c.entries.isEmpty())};val names=(0..1).flatMap{s->(0..4).map{SdControlHost.port(s,it)}}+(0..3).map{SdClockHost.port(it)};for(name in names){val c=Context(base);c.entries[name]=object:MmioDevice{override fun read(offset:Long,size:Int)=0L;override fun write(offset:Long,size:Int,value:Long){}};assertFails{create(c)};assertEquals(1,c.entries.size)}}
 @Test fun onlyExactHalfwordsAndU16WritesWithAtomicInvalidAccesses(){val c=Context(input());val h=create(c);val before=h.state();for(i in 0..3){val p=port(c,i);for(w in listOf(0,1,4,8)){assertFails{p.read(0,w)};assertFails{p.write(0,w,0)};assertEquals(before,h.state())};for(off in listOf(-2L,1L,2L,4L)){assertFails{p.read(off,2)};assertFails{p.write(off,2,0)};assertEquals(before,h.state())};for(v in listOf(-1L,65536L)){assertFails{p.write(0,2,v)};assertEquals(before,h.state())}}}
 @Test fun frozenInputsBoundedDiagnosticsLifecycleAndRestart(){val samples=MutableList<Any?>(300){0};val c=Context(input(samples));val h=create(c);samples[0]=1;repeat(300){assertEquals(0xa550L,port(c,0).read(0,2))};assertEquals(300L,h.state()["clockReadCount"]);assertEquals(256,(h.state()["clockAccesses"]as List<*>).size);assertEquals(true,h.state()["clockAccessLogTruncated"]);h.applySettings(mapOf("profile" to SdHostFactory.CLOCK_PROFILE));assertFails{h.applySettings(mapOf("inputFile" to "other.yaml"))};val control=c.ports.find(SdControlHost.port(0,0),MmioDevice::class.java)!!;h.close();h.close();assertFails{h.start()};assertFails{port(c,0).read(0,2)};assertFails{port(c,0).write(0,2,1)};assertFails{control.read(0,4)};assertEquals(true,(h.state()["controlState"]as Map<*,*>)["closed"])}
}
